import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text for display to the customer.
 * @param {{ number?: string, customerId: string, dueDate?: string, payments?: Array<{ amount: number }>, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, voucher?: { amount: number } }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : '(Unknown customer)';

  const lines = [];

  // First line: invoice number or DRAFT
  const number = invoice.number || 'DRAFT';
  lines.push(number);

  // Second line: customer name
  lines.push(customerName);

  // Line items with discounts
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let lineText = `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    if ((line.discountPercent ?? 0) > 0) {
      const discount = total * (line.discountPercent / 100);
      lineText += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }
    lines.push(lineText);
  }

  // Summary lines
  const totals = invoiceTotals(invoice);
  lines.push(`VAT: ${formatEuros(totals.vat)}`);

  // Voucher (if present)
  if (invoice.voucher) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  // Total
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date (if present)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount (if payments present)
  if (invoice.payments && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

