import assert from 'node:assert';
import { describe, it } from 'node:test';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

describe('renderInvoiceText', () => {
  it('renders a draft invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('DRAFT'));
    assert(text.includes('Blue Fern Bakery'));
    assert(text.includes('5x Design work (hour) @ €85.00 = €425.00'));
    assert(text.includes('VAT: €89.25'));
    assert(text.includes('Total: €514.25'));
  });

  it('renders an issued invoice with number', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    const text = renderInvoiceText(issueResult.value);

    assert(text.includes('INV-2025-0001'));
    assert(!text.includes('DRAFT'));
    assert(text.includes('Blue Fern Bakery'));
    assert(text.includes('5x Design work (hour) @ €85.00 = €425.00'));
    assert(text.includes('VAT: €89.25'));
    assert(text.includes('Total: €514.25'));
  });

  it('renders multiple line items', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('DRAFT'));
    assert(text.includes('Blue Fern Bakery'));
    assert(text.includes('5x Design work (hour) @ €85.00 = €425.00'));
    assert(text.includes('3x Development (hour) @ €95.00 = €285.00'));
    assert(text.includes('VAT: €149.10'));
    assert(text.includes('Total: €859.10'));
  });

  it('formats amounts correctly with thousands separator', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'LOGO-PACK', qty: 2 }],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    // LOGO-PACK is 120000 cents = €1,200.00
    assert(text.includes('2x Logo package @ €1,200.00 = €2,400.00'));
    assert(text.includes('VAT: €504.00'));
    assert(text.includes('Total: €2,904.00'));
  });

  it('formats line items with different VAT rates', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'PRINT-A4', qty: 9 }, // 37 cents, 9% VAT
        { sku: 'DEV-HOUR', qty: 2 },   // 9500 cents, 21% VAT
      ],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('9x Printed flyer A4 (each) @ €0.37 = €3.33'));
    assert(text.includes('2x Development (hour) @ €95.00 = €190.00'));
    assert(text.includes('VAT: €40.20'));
    assert(text.includes('Total: €233.53'));
  });

  it('renders output as multiple lines', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);
    const outputLines = text.split('\n');

    assert.equal(outputLines.length, 6);
    assert.equal(outputLines[0], 'DRAFT');
    assert.equal(outputLines[1], 'Blue Fern Bakery');
    assert(outputLines[2].includes('5x Design work (hour)'));
    assert(outputLines[3].startsWith('VAT:'));
    assert(outputLines[4].startsWith('Total:'));
    assert(outputLines[5].startsWith('Due:'));
  });

  it('uses customer name from lookup', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('Blue Fern Bakery'));
  });

  it('handles different quantities correctly', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('1x Design work (hour) @ €85.00 = €85.00'));
    assert(text.includes('VAT: €17.85'));
    assert(text.includes('Total: €102.85'));
  });

  it('calculates correct totals for multiple lines', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 3 },   // 3 * 8500 = 25500
        { sku: 'DEV-HOUR', qty: 2 },   // 2 * 9500 = 19000
        { sku: 'COPY-HOUR', qty: 4 },  // 4 * 6000 = 24000
      ],
    });

    assert(invoiceResult.ok);
    const text = renderInvoiceText(invoiceResult.value);

    // 25500 + 19000 + 24000 = 68500 = €685.00
    // VAT: 5355 + 3990 + 5040 = 14385 = €143.85
    // Total: 685 + 143.85 = 828.85
    assert(text.includes('Total: €828.85'));
  });

  it('renders with invoice number for issued invoices', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const issueResult = issueInvoice(invoiceResult.value, existingNumbers);

    assert(issueResult.ok);
    const text = renderInvoiceText(issueResult.value);

    assert(text.includes('INV-2025-0003'));
    assert(text.includes('VAT:'));
    assert(text.includes('Total:'));
    assert(!text.includes('DRAFT'));
  });

  it('displays line discounts', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [
        { qty: 5, name: 'Item A', unitPrice: 1000, discountPercent: 10 },
        { qty: 2, name: 'Item B', unitPrice: 2000, discountPercent: 0 },
      ],
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('(10% off: -€5.00)'));
    assert(!text.includes('0% off'));
  });

  it('displays voucher before total', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [{ qty: 1, name: 'Item', unitPrice: 1000, discountPercent: 0 }],
      voucher: { code: 'SAVE10', amount: 500 },
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('Voucher: -€5.00'));
    const voucherIndex = text.indexOf('Voucher:');
    const totalIndex = text.indexOf('Total:');
    assert(voucherIndex < totalIndex);
  });

  it('displays due date', () => {
    const invoice = {
      customerId: 'C-001',
      dueDate: '2026-12-25',
      lines: [{ qty: 1, name: 'Item', unitPrice: 1000, discountPercent: 0 }],
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('Due: 2026-12-25'));
  });

  it('displays paid amount for single payment', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [{ qty: 1, name: 'Item', unitPrice: 1000, discountPercent: 0 }],
      payments: [{ amount: 500 }],
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('Paid: €5.00'));
  });

  it('displays total paid for multiple payments', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [{ qty: 1, name: 'Item', unitPrice: 1000, discountPercent: 0 }],
      payments: [{ amount: 300 }, { amount: 200 }, { amount: 500 }],
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('Paid: €10.00'));
  });

  it('does not display paid line when no payments', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [{ qty: 1, name: 'Item', unitPrice: 1000, discountPercent: 0 }],
      payments: [],
    };
    const text = renderInvoiceText(invoice);

    assert(!text.includes('Paid:'));
  });

  it('displays complete invoice with all enhancements', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const issueResult = issueInvoice(invoiceResult.value, []);
    assert(issueResult.ok);

    const fullyEnhancedInvoice = {
      ...issueResult.value,
      dueDate: '2026-01-15',
      voucher: { code: 'SAVE20', amount: 2000 },
      payments: [{ amount: 5000 }, { amount: 3000 }],
    };

    const text = renderInvoiceText(fullyEnhancedInvoice);

    assert(text.includes('INV-2025-0001'));
    assert(text.includes('(10% off:'));
    assert(text.includes('Voucher: -€20.00'));
    assert(text.includes('Total:'));
    assert(text.includes('Due: 2026-01-15'));
    assert(text.includes('Paid: €80.00'));

    const lines = text.split('\n');
    const voucherLine = lines.findIndex(l => l.includes('Voucher:'));
    const totalLine = lines.findIndex(l => l.includes('Total:'));
    const dueLine = lines.findIndex(l => l.includes('Due:'));
    const paidLine = lines.findIndex(l => l.includes('Paid:'));

    assert(voucherLine < totalLine);
    assert(totalLine < dueLine);
    assert(dueLine < paidLine);
  });

  it('displays discount correctly with large percentages', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [{ qty: 10, name: 'Item', unitPrice: 1000, discountPercent: 25 }],
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('(25% off: -€2,500.00)'));
  });

  it('displays discount with decimal percentages', () => {
    const invoice = {
      customerId: 'C-001',
      lines: [{ qty: 10, name: 'Item', unitPrice: 1000, discountPercent: 2.5 }],
    };
    const text = renderInvoiceText(invoice);

    assert(text.includes('(2.5% off: -€250.00)'));
  });
});

